cd "C:/visual projects/game" && cat > tests/unit/test_models.gd <<'EOF'
extends GutTest
## Модели из assets/models/ грузятся, масштаб 1 юнит = 1 м (инвариант 13).
## Набор моделей сейчас пуст (убраны по слову владельца) — тест проходит на пустом наборе.
## Новая модель обязана получить строку в HEIGHTS: без неё тест падает, проверка не отключается молча.

const DIR := "res://assets/models/"
const TOL := 0.05
## имя модели (без .glb) -> ожидаемая высота по Y, м
const HEIGHTS := {}


func _glbs() -> Array[String]:
	var out: Array[String] = []
	var d := DirAccess.open(DIR)
	if d == null:
		return out
	for f in d.get_files():
		if f.ends_with(".glb"):
			out.append(f.get_basename())
	return out


func _height(n: Node) -> float:
	var box := AABB()
	var first := true
	for m in n.find_children("*", "MeshInstance3D", true, false):
		var mi := m as MeshInstance3D
		var b := mi.global_transform * mi.get_aabb()
		box = b if first else box.merge(b)
		first = false
	return box.size.y


func test_all_models_load_and_have_expected_height() -> void:
	var names := _glbs()
	assert_eq(names.size() > 0 or HEIGHTS.is_empty(), true, "в HEIGHTS есть модели, а файлов нет")
	for name in names:
		var scene := load(DIR + name + ".glb") as PackedScene
		assert_not_null(scene, name)
		assert_true(HEIGHTS.has(name), "%s: нет строки в HEIGHTS (tests/unit/test_models.gd)" % name)
		if scene == null or not HEIGHTS.has(name):
			continue
		var inst := scene.instantiate()
		add_child_autofree(inst)
		assert_almost_eq(_height(inst), float(HEIGHTS[name]), TOL, name)
	for name in HEIGHTS:
		assert_true(names.has(name), "%s: есть в HEIGHTS, нет файла" % name)
EOF
python - <<'EOF'
import re
p="assets/CREDITS.md"
s=open(p,encoding="utf-8").read()
s=re.sub(r"\| `models/\*\.glb` .*\n\| `models/\*_atlas\.png` .*\n","",s)
s=s.replace("в репо попадают лишь вшитые в `models/mage.glb` ретаргетнутые","в репо попадают лишь вшитые в модель персонажа в `models/*.glb` ретаргетнутые")
open(p,"w",encoding="utf-8",newline="\n").write(s)
EOF
sed -n 1,12p assets/CREDITS.md

